INSERT INTO feature VALUES('command-codec','runtime','The canonical image of a closed command',NULL,'implemented','notable',NULL,'A closed command of the sequent IL has a canonical image: the nodes that its root reaches, each after its children and named by its position, with the definitions that it unfolds, as one flat value of the value plane. Equal commands give equal bytes. The core types and codes that its nodes name cross as one content table in the node codec of the content crate, one place for each distinct content, and a command that names none keeps the bytes of the image alone. The read mints the table, then each node into a fresh arena over children that it holds, under a ceiling of nodes, and judges the root again with `check_command`.','runtime-emitter core-content','crates/runtime-emitter/tests/image.rs crates/runtime-stencils/tests/image.rs','crate-tests',NULL);
